import { cpSync, mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildDossier } from './vendor/makefun-game.ts';

// The hand-in includes the game's browser-ready files and its screenshots.
// These folders preserve the assets needed to view and understand the game.
// They are copied into the selected output directory for the grader.
// The dossier gathers the game details and screenshot data into one file.
// Its contents are generated by the repository's supplied dossier builder.
// The destination is never cleared because it may be a mounted volume.
const outputDir = process.env.MAKEFUN_OUTPUT_DIR || '/output';
const scriptDir = dirname(fileURLToPath(import.meta.url));

mkdirSync(outputDir, { recursive: true });
cpSync(join(scriptDir, 'game'), join(outputDir, 'game'), { recursive: true });
cpSync(join(scriptDir, 'screenshots'), join(outputDir, 'screenshots'), { recursive: true });

const dossier = buildDossier(outputDir, {
  text_max_bytes: 163840,
  screenshots: { max: 4, max_bytes: 262144 },
  game_max_files: 993,
  game_max_bytes: 50331648,
  game_path_max_bytes: 1000,
});
writeFileSync(join(outputDir, 'dossier.json'), dossier);

console.log(`Wrote game/, screenshots/, and dossier.json to ${outputDir}.`);
